import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class DocumentExtractionError(Exception):
    pass


def _read_bytes(source: Any) -> bytes:
    if isinstance(source, bytes):
        return source
    if isinstance(source, str):
        with open(source, "rb") as f:
            return f.read()
    if hasattr(source, "read"):
        data = source.read()
        if not isinstance(data, bytes):
            raise DocumentExtractionError("File-like object must return bytes.")
        return data
    raise DocumentExtractionError("document must be bytes, a file path, or a binary file-like object.")


def _safe_float(value: Any) -> Optional[float]:
    try:
        if value is None:
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _normalize_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _extract_summary_fields(expense_document: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    summary: Dict[str, Dict[str, Any]] = {}
    for field in expense_document.get("SummaryFields", []) or []:
        type_info = field.get("Type", {}) or {}
        field_type = _normalize_text(type_info.get("Text"))
        if not field_type:
            continue

        value_detection = field.get("ValueDetection", {}) or {}
        label_detection = field.get("LabelDetection", {}) or {}

        value_text = _normalize_text(value_detection.get("Text"))
        label_text = _normalize_text(label_detection.get("Text"))
        confidence = _safe_float(value_detection.get("Confidence"))
        if confidence is None:
            confidence = _safe_float(type_info.get("Confidence"))

        summary[field_type] = {
            "value": value_text,
            "label": label_text,
            "confidence": confidence,
            "raw": field,
        }
    return summary


def _pick_field(
    summary_fields: Dict[str, Dict[str, Any]],
    candidates: List[str],
) -> Dict[str, Any]:
    for candidate in candidates:
        if candidate in summary_fields:
            return summary_fields[candidate]
    return {"value": None, "label": None, "confidence": None, "raw": None}


def extract_and_validate_invoice_fields(
    document: Any,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 80.0,
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    if required_fields is None:
        required_fields = ["invoice_number", "invoice_date", "vendor_name", "total_amount"]

    alias_map = {
        "invoice_number": ["INVOICE_RECEIPT_ID"],
        "invoice_date": ["INVOICE_RECEIPT_DATE"],
        "vendor_name": ["VENDOR_NAME"],
        "total_amount": ["TOTAL"],
        "subtotal_amount": ["SUBTOTAL"],
        "tax_amount": ["TAX"],
        "due_date": ["DUE_DATE"],
        "vendor_address": ["VENDOR_ADDRESS"],
        "currency": ["CURRENCY"],
    }

    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    textract = boto3.client("textract", region_name=region)

    document_bytes = _read_bytes(document)

    try:
        response = textract.analyze_expense(Document={"Bytes": document_bytes})
    except (BotoCoreError, ClientError) as e:
        raise DocumentExtractionError(f"Amazon Textract AnalyzeExpense failed: {e}") from e

    expense_documents = response.get("ExpenseDocuments", []) or []
    if not expense_documents:
        raise DocumentExtractionError("No expense documents were detected by Amazon Textract.")

    primary_doc = expense_documents[0]
    summary_fields = _extract_summary_fields(primary_doc)

    extracted_fields: Dict[str, Dict[str, Any]] = {}
    validation: Dict[str, Dict[str, Any]] = {}

    for requested_name in required_fields:
        candidates = alias_map.get(requested_name, [requested_name])
        field_data = _pick_field(summary_fields, candidates)
        extracted_fields[requested_name] = {
            "value": field_data["value"],
            "confidence": field_data["confidence"],
            "source_type": next((c for c in candidates if c in summary_fields), None),
            "label": field_data["label"],
        }

        present = field_data["value"] is not None
        confidence = field_data["confidence"]
        confidence_ok = confidence is not None and confidence >= float(min_confidence)

        validation[requested_name] = {
            "required": True,
            "present": present,
            "confidence": confidence,
            "min_confidence": float(min_confidence),
            "confidence_ok": confidence_ok,
            "valid": present and confidence_ok,
        }

    overall_valid = all(item["valid"] for item in validation.values())

    return {
        "provider": "aws_textract",
        "operation": "AnalyzeExpense",
        "model_family": "Amazon Textract AnalyzeExpense",
        "region": region,
        "document_metadata": {
            "expense_index": 0,
            "expense_count": len(expense_documents),
        },
        "fields": extracted_fields,
        "validation": validation,
        "overall_valid": overall_valid,
        "raw_response": response,
    }
